/** current UI language code (en/fr/es/…), from the radio/menu picker. */
export function uiLang(): Lang {
  try { return menuLanguage(); } catch { return "fr"; }
}

/** translate a French source string to the current language (French = identity). */
// Country names in EVERY language the game speaks, without a table: the browser
// knows them all from the ISO code. Falls back to the French name for the ones
// Intl has no region for (the home nations, "gb-eng" and friends).
const regionCache = new Map<string, string>();
/**
 * The ISO code hiding inside a flag emoji.
 *
 * 🇮🇹 is not a picture, it is the two letters I and T written as regional
 * indicator symbols — so a flag we already store next to a player is itself the
 * country code, and countryName can name it in the reader's language without us
 * keeping a second table of codes.
 */
export function isoFromFlag(flag: string): string {
  const cp = Array.from(flag ?? "").map((c) => c.codePointAt(0) ?? 0)
    .filter((n) => n >= 0x1f1e6 && n <= 0x1f1ff);
  if (cp.length !== 2) return "";                 // 🌍, 🏴󠁧󠁢󠁥󠁮󠁧󠁿 and friends have no code
  return cp.map((n) => String.fromCharCode(n - 0x1f1e6 + 65)).join("");
}

/**
 * The ISO code behind a French country name.
 *
 * Country names reach the menus already written in French ("Allemagne"), with
 * no code attached — and a hand-written French→code table would go stale the
 * moment someone adds a nation. So build the index the other way round, once:
 * ask Intl for the French name of every two-letter code and keep the ones it
 * actually names. A name it does not know (Angleterre, Écosse — parts of a
 * country, not countries) simply falls through to the hand-translated row.
 */
let frenchIso: Map<string, string> | null = null;
export function isoFromFrench(french: string): string {
  if (!frenchIso) {
    frenchIso = new Map();
    try {
      const fr = new Intl.DisplayNames(["fr"], { type: "region" });
      for (let a = 65; a <= 90; a++) {
        for (let b = 65; b <= 90; b++) {
          const code = String.fromCharCode(a, b);
          const name = fr.of(code);
          if (name && name !== code) frenchIso.set(name.toLowerCase(), code);
        }
      }
    } catch { /* no Intl data: every lookup just misses */ }
  }
  return frenchIso.get((french ?? "").toLowerCase()) ?? "";
}

export function countryName(iso: string, french: string): string {
  const lang = uiLang();
  const key = lang + "|" + iso + "|" + french;   // "" iso is shared by several names
  const hit = regionCache.get(key);
  if (hit !== undefined) return hit;
  let out = L(french);   // hand-translated fallback (England, Scotland, Wales…)
  const code = (iso || isoFromFrench(french)).toUpperCase();
  if (/^[A-Z]{2}$/.test(code)) {
    try {
      const dn = new Intl.DisplayNames([lang], { type: "region" });
      out = dn.of(code) ?? out;
    } catch { /* keep the fallback */ }
  }
  regionCache.set(key, out);
  return out;
}

export function L(fr: string): string {
  const lang = uiLang();
  if (lang === "fr" || !lang) return fr;
  const row = T[fr];
  if (!row) return fr;
  // Exact language first, then the base of a regional code (zh-CN -> zh), then
  // English as the widest fallback — a Japanese player reading English beats a
  // Japanese player reading French.
  const base = lang.split("-")[0] ?? lang;
  return row[lang] ?? row[base] ?? row.en ?? fr;
}

/** translate a "CAPITAINE — FRANCE"-style header keeping the dynamic tail. */
export function Lcaptain(nation: string): string {
  return `${L("CAPITAINE")} — ${nation.toUpperCase()}`;
}

/** re-render menus when the language changes. */
export function onLangChange(cb: () => void): void {
  window.addEventListener("gpf-langchange", cb);
}
export function fireLangChange(): void {
  window.dispatchEvent(new Event("gpf-langchange"));
}
